void inspect_memory(void) {
    /* a) Read 32-bit integer on a little-endian CPU (least-significant byte at lowest address) */
    volatile uint32_t *int_ptr = (volatile uint32_t *)0x000c0000;
    uint32_t val = *int_ptr; /* Bytes [04, 03, 02, 01] -> 0x01020304 in little-endian! */
    printf("32-bit value: 0x%08x\n", val);

    /* b) Print null-terminated ASCII string starting at 0x000c0004 */
    const char *str_ptr = (const char *)0x000c0004;
    printf("String: %s\n", str_ptr);

    /* c) Copy 5 lines (e.g., 5 * 16 = 80 bytes) from src starting at byte 0x04 to 0x000c0000 */
    void *dst = (void *)0x000c0000;
    const void *src = (const void *)0x000c0010; /* example source */
    memmove(dst, src, 5 * 16); /* memmove is safe even if regions overlap! */
}

