#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>

int main(void) {
    int wstatus;
    pid_t pid = fork(); /* 1. Duplicate parent -> child gets 0, parent gets child PID */

    if (pid < 0) {
        perror("fork failed"); /* Check errno on failure (e.g., max processes / OOM) */
        exit(1);
    } else if (pid == 0) {
        /* Child process */
        char *argv[] = {"ls", "-l", NULL};
        execvp("ls", argv); /* 2. Replace binary image; PID & open FDs are preserved! */
        perror("execvp failed"); /* Only reached if exec fails */
        exit(127);
    } else {
        /* Parent process */
        waitpid(pid, &wstatus, 0); /* 3. Block until child exits, read status, free child PCB */
        if (WIFEXITED(wstatus)) {
            printf("Child exited with code %d\n", WEXITSTATUS(wstatus));
        }
    }
    return 0; /* C runtime calls exit(0) automatically */
}

