blocks.solution:
const procs = [
  { id: 'P1', arr: 0, dur: 6, rem: 6 },
  { id: 'P2', arr: 2, dur: 9, rem: 9 },
  { id: 'P3', arr: 3, dur: 2, rem: 2 },
  { id: 'P4', arr: 6, dur: 4, rem: 4 }
];
const total = procs.reduce((s, p) => s + p.dur, 0);
for (let t = 0; t < total; t++) {
  const ready = procs.filter(p => p.arr <= t && p.rem > 0).sort((a, b) => a.rem - b.rem || a.arr - b.arr);
  const cur = ready[0];
  cur.rem--;
  if (cur.rem === 0) cur.finish = t + 1;
}
const avgWait = procs.reduce((s, p) => s + (p.finish - p.arr - p.dur), 0) / procs.length;
console.log(avgWait.toFixed(2));

